const assignedTargets = LEGACY_EASY_TARGETS.filter(({ batchId }) =>
  ASSIGNED_BATCH_IDS.has(batchId));

const titleById = new Map<string, CategoryTitle>(ACCESSIBLE_CATEGORY_TITLES.map((title) =>
  [title.categorySetId, title]));

function sourceTitle(page: string): string {
  return decodeURIComponent(page.split('#', 1)[0]!.replaceAll('_', ' '));
}

function buildQuestion(
  categorySetId: string,
  fact: Fact,
  tier: 1 | 2 | 3 | 4 | 5,
): AccessibleQuestion {
  const [
    factKey,
    subjectKey,
    clueEn,
    clueEt,
    responseEn,
    responseEt,
    explanationEn,
    explanationEt,
    wikipediaPage,
    variantsEn = [],
    variantsEt = [],
  ] = fact;
  return {
    key: `${categorySetId}:${factKey}`,
    tier,
    subjectKey,
    clue: { en: clueEn, et: clueEt },
    response: { en: responseEn, et: responseEt },
    acceptedVariants: { en: variantsEn, et: variantsEt },
    explanation: { en: explanationEn, et: explanationEt },
    source: {
      sourceId: `wikipedia:${wikipediaPage.toLocaleLowerCase('en')}`,
      title: sourceTitle(wikipediaPage),
      url: `https://en.wikipedia.org/wiki/${wikipediaPage}`,
      license: 'CC-BY-SA-4.0',
      retrievedAt: '2026-08-28',
    },
  };
}

const rawCategories: readonly AccessibleCategory[] = assignedTargets.map((target) => {
  const title = titleById.get(target.categorySetId);
  if (title === undefined) {
    throw new Error(`Missing approved category title: ${target.categorySetId}`);
  }
  const facts = FACTS[target.categorySetId];
  if (facts === undefined) {
    throw new Error(`Missing authored facts: ${target.categorySetId}`);
  }
  return {
    categorySetId: target.categorySetId,
    batchId: target.batchId,
    name: title.name,
    questions: facts.map((fact, index) =>
      buildQuestion(target.categorySetId, fact, (index + 1) as 1 | 2 | 3 | 4 | 5)),
  };
});

export const SOCIETY_TECHNOLOGY_CULTURE_CATEGORIES = validateAccessibleCorpus(
  rawCategories,
  assignedTargets,
);
